            setTimeout(() => {
              if (this.isPlaybackInProgress) {
                this.isPlaybackInProgress = false;
              }
            }, 5000);

            return Result.Ok(undefined);
          },
          (error) => {
            const handledError = this.errorHandler.handleError(error, {
              component: 'AudioPlaybackService',
              action: 'playTrack'
