   */
  handleError(error: unknown, context?: ErrorContext): DomainError {
    const domainError = this.mapToDomainError(error);
    const enrichedError = this.enrichWithContext(domainError, context);

    this.logError(enrichedError, context);

    return enrichedError;
  }

  /**
   * Format error for user display
   */
  getUserFriendlyMessage(error: DomainError): string {
    if (error.is(ErrorHandlingDomainError.VALIDATION_ERROR)) {
      return this.formatValidationError(error as ValidationError);
    }

    if (error.is(ErrorHandlingDomainError.NETWORK_ERROR)) {
      return this.formatNetworkError(error as NetworkError);
    }

    return 'An unexpected error occurred. Please try again later.';
  }

  /**
   * Retry operator for Observable with automatic error handling
   */
  withRetry<T>(config: Partial<RetryConfig> = {}) {
    const retryConfig = { ...this.defaultRetryConfig, ...config };

    return (source: Observable<T>) => source.pipe(
      retry({
        count: retryConfig.maxRetries,
        delay: (error, retryIndex) => {
          const shouldRetry = this.shouldRetry(error, retryIndex, retryConfig);

          if (!shouldRetry) {
            return throwError(() => this.handleError(error));
          }

          const delay = this.calculateDelay(retryIndex, retryConfig);
          console.warn(`Retry attempt ${String(retryIndex + 1)}/${String(retryConfig.maxRetries)} in ${String(delay)}ms`, error);

          return timer(delay);
        }
      })
    );
  }

  /**
   * Check if request should be retried
   */
  shouldRetry(error: unknown, retryCount: number, config: RetryConfig): boolean {
    if (retryCount >= config.maxRetries) {
      return false;
    }

    if (error instanceof HttpErrorResponse) {
      return config.retryableStatusCodes.includes(error.status);
    }

    if (ApplicationError.is(error) && error.is(ErrorHandlingDomainError.NETWORK_ERROR)) {
      return true;
    }

    return false;
  }

  /**
   * Calculate retry delay
   */
  calculateDelay(retryCount: number, config: RetryConfig): number {
    if (!config.exponentialBackoff) {
      return config.delay;
    }

    const exponentialDelay = config.delay * Math.pow(2, retryCount);
    const jitter = Math.random() * 1000;

    return Math.min(exponentialDelay + jitter, 30000);
  }

  private mapToDomainError(error: unknown): DomainError {
    if (ApplicationError.is(error)) {
      return error as DomainError;
    }

    if (error instanceof HttpErrorResponse) {
      return this.handleHttpErrorResponse(error);
    }

    if (error instanceof Error) {
      return this.handleJavaScriptError(error);
    }

    if (typeof error === 'string') {
      return createUnknownError(error);
    }

    return createUnknownError('Unknown error', { originalError: error });
  }

  private handleHttpErrorResponse(error: HttpErrorResponse): NetworkError {
    const status = error.status as HttpStatusCode;
    let message: string;

    // Check for custom server message
    if (isObject(error.error) && 'message' in error.error) {
      message = (error.error as { message: string }).message;
    } else if (status in HTTP_ERROR_MESSAGES) {
      message = HTTP_ERROR_MESSAGES[status];
    } else {
      message = (error.message !== '' ? error.message : undefined) ?? `HTTP error ${String(status)}`;
    }

    const networkError = createNetworkError(message, status);

    // Add server response details
    if (isObject(error.error)) {
      networkError.details = {
        ...networkError.details,
        serverResponse: error.error,
        url: error.url ?? undefined
      };
    }

    return networkError;
  }

  private handleJavaScriptError(error: Error): DomainError {
    if (error.name === 'NetworkError' || error.message.includes('Failed to fetch')) {
      return createNetworkError('Network connection error');
    }

    if (error.name === 'AbortError') {
      return createNetworkError('Request was cancelled');
    }

    if (error.name === 'TimeoutError') {
      return createNetworkError('Request timeout');
    }

    return createUnknownError(error.message, {
      stack: error.stack,
      name: error.name
    });
  }

  private enrichWithContext(error: DomainError, context?: ErrorContext): DomainError {
    if (context === undefined) {
      return error;
    }

    error.details = {
      ...error.details,
      context: {
        ...context,
        timestamp: context.timestamp ?? new Date()
      }
    };

    return error;
  }

  private logError(error: DomainError, context?: ErrorContext): void {
    const logLevel = this.getLogLevel(error);
    const logData = {
      error: {
        type: error.type,
        message: error.message,
        details: error.details
      },
      context,
      timestamp: new Date().toISOString()
    };

    switch (logLevel) {
      case 'error':
        console.error('[ErrorHandlingService]', logData);
        break;
      case 'warn':
        console.warn('[ErrorHandlingService]', logData);
        break;
      case 'info':
        console.info('[ErrorHandlingService]', logData);
        break;
    }
  }

  private getLogLevel(error: DomainError): 'error' | 'warn' | 'info' {
    if (error.is(ErrorHandlingDomainError.VALIDATION_ERROR)) {
      return 'warn';
    }

    if (error.is(ErrorHandlingDomainError.NETWORK_ERROR)) {
      const status = error.details?.['status'] as HttpStatusCode | undefined;
      if (isDefined(status) && status >= HttpStatusCode.INTERNAL_SERVER_ERROR) {
        return 'error';
      }
      if (isDefined(status) && status >= HttpStatusCode.BAD_REQUEST) {
        return 'warn';
      }
    }

    return 'error';
  }

    private formatValidationError(error: ValidationError): string {
    const fields = error.details?.['fields'] as Record<string, string[]> | undefined;

    if (fields === undefined) {
      return error.message;
    }

    const fieldErrors = Object.entries(fields)
      .map(([field, errors]) => `${field}: ${errors.join(', ')}`)
      .join('; ');

    return `Validation error: ${fieldErrors}`;
  }

  private formatNetworkError(error: NetworkError): string {
    const status = error.details?.['status'] as HttpStatusCode | undefined;

    if (isDefined(status)) {
      switch (status) {
        case HttpStatusCode.UNAUTHORIZED:
          return HTTP_ERROR_MESSAGES[status];
        case HttpStatusCode.FORBIDDEN:
          return HTTP_ERROR_MESSAGES[status];
        case HttpStatusCode.NOT_FOUND:
          return HTTP_ERROR_MESSAGES[status];
        case HttpStatusCode.INTERNAL_SERVER_ERROR:
          return HTTP_ERROR_MESSAGES[status];
        case HttpStatusCode.BAD_GATEWAY:
          return HTTP_ERROR_MESSAGES[status];
        case HttpStatusCode.SERVICE_UNAVAILABLE:
          return HTTP_ERROR_MESSAGES[status];
        default:
          return error.message;
      }
    }

    return 'Network error. Please check your internet connection';
  }
}

import { Component, EventEmitter, Input, Output } from '@angular/core';

export interface FilterOptions {
  search?: string;
  genre?: string;
  artist?: string;
  sortBy?: string;
  sortOrder?: 'asc' | 'desc';
}

@Component({
  selector: 'app-track-filter',
  standalone: true,
  imports: [],
  templateUrl: './track-filter.component.html',
  styleUrl: './track-filter.component.scss'
})
export class TrackFilterComponent {
  @Input() genres: string[] = [];
  @Input() artists: string[] = [];
  @Input() currentFilters: FilterOptions = {};

  @Output() filtersChange = new EventEmitter<FilterOptions>();

  onSearchChange(search: string): void {
    this.filtersChange.emit({ ...this.currentFilters, search });
  }

  onGenreChange(genre: string): void {
    this.filtersChange.emit({ ...this.currentFilters, genre });
  }

  onArtistChange(artist: string): void {
    this.filtersChange.emit({ ...this.currentFilters, artist });
  }

  onSortChange(sortBy: string, sortOrder: 'asc' | 'desc'): void {
    this.filtersChange.emit({ ...this.currentFilters, sortBy, sortOrder });
  }

  clearFilters(): void {
    this.filtersChange.emit({});
  }
}

import { Injectable } from '@angular/core';
import { z } from 'zod';
import { ValidatedApiService } from './validated-api.service';
import { Observable } from 'rxjs';
import { Result } from '../lib/monads';
import { DomainError } from '../lib/application-error';

export interface Genre {
  name: string;
}

export const GenreSchema = z.object({
  name: z.string().min(1, 'The genre name cannot be empty.')
});

export const GenreCreateSchema = z.object({
  name: z.string().min(1, 'The genre name cannot be empty.')
});

export const GenreUpdateSchema = z.object({
  name: z.string().min(1, 'The genre name cannot be empty.').optional()
});

export type GenreCreate = z.infer<typeof GenreCreateSchema>;
export type GenreUpdate = z.infer<typeof GenreUpdateSchema>;

export const GenreListSchema = z.array(z.string().min(1));
export const GenreResponseSchema = z.string().min(1);


@Injectable({
  providedIn: 'root'
})
export class ValidatedGenreApiService extends ValidatedApiService<
  Genre,
  GenreCreate,
  GenreUpdate
> {
  protected override readonly baseUrl = '/api';
  protected readonly entitySchema = GenreSchema;
  protected readonly createSchema = GenreCreateSchema;
  protected readonly updateSchema = GenreUpdateSchema;

  /**
   * Get all genres (returns an array of strings)
   */
  public getAll(): Observable<Result<string[], DomainError>> {
    return this.getValidated<string[]>('genres', GenreListSchema);
  }

  /**
   * An alternative method for compatibility with the old API
   */
  public getAllGenres(): Observable<Result<string[], DomainError>> {
    return this.getAll();
  }

  /**
   * Get genre by ID (returns a string)
   */
  public getGenreById(id: string): Observable<Result<string, DomainError>> {
    return this.getValidated<string>(`genres/${id}`, GenreResponseSchema);
  }

  /**
   * Create a new genre
   */
  public createGenre(name: string): Observable<Result<string, DomainError>> {
    return this.postValidated<string>('genres', { name }, GenreResponseSchema, {
      requestSchema: GenreCreateSchema
    });
  }

  /**
   * Update genre
   */
  public updateGenre(id: string, name: string): Observable<Result<string, DomainError>> {
    return this.putValidated<string>(`genres/${id}`, { name }, GenreResponseSchema, {
      requestSchema: GenreCreateSchema
    });
  }

  /**
   * Delete genre
   */
  public deleteGenre(id: string): Observable<Result<boolean, DomainError>> {
    return this.deleteValidated<boolean>(`genres/${id}`, z.boolean());
  }
}

