import { ChangeDetectionStrategy, ChangeDetectorRef, Component, inject, OnInit } from '@angular/core';
import { NgForOf, NgIf } from '@angular/common';
import { AbstractControl, FormBuilder, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { COMMA, ENTER } from '@angular/cdk/keycodes';
import {
  MAT_DIALOG_DATA,
  MatDialogActions,
  MatDialogContent,
  MatDialogRef,
  MatDialogTitle
} from '@angular/material/dialog';
import { MatChip, MatChipInputEvent, MatChipRemove, MatChipSet } from '@angular/material/chips';
import { MatProgressSpinner } from '@angular/material/progress-spinner';
import { MatError, MatFormField, MatLabel } from '@angular/material/form-field';
import { MatInput } from '@angular/material/input';
import { MatOption, MatSelect} from '@angular/material/select';
import { MatIcon } from '@angular/material/icon';
import { MatButton } from '@angular/material/button';
import { isArray, TestIdDirective, ToastService, zodValidator, OptimizedImageComponent } from '@app/shared';
import { GenreQueryService, Track, TrackQueryService, TrackUpdate, TrackUpdateSchema } from '@app/entities';

interface TrackEditModalData {
  track: Track;
}

@Component({
  selector: 'app-track-edit-modal',
  standalone: true,
  imports: [
    MatDialogTitle,
    TestIdDirective,
    MatProgressSpinner,
    NgIf,
    ReactiveFormsModule,
    MatDialogContent,
    MatFormField,
    MatInput,
    MatSelect,
    MatOption,
    NgForOf,
    MatChipSet,
    MatChip,
    MatChipRemove,
    MatIcon,
    MatError,
    MatDialogActions,
    MatButton,
    MatLabel,
    OptimizedImageComponent,
  ],
  templateUrl: './track-edit-modal.component.html',
  styleUrl: './track-edit-modal.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class TrackEditModalComponent implements OnInit {
  public form!: FormGroup;
  public genres: string[] = [];
  public loading = false;
  public submitting = false;
  public readonly separatorKeysCodes = [ENTER, COMMA] as const;

  private fb = inject(FormBuilder);
  private trackQueryService = inject(TrackQueryService);
  private genreQueryService = inject(GenreQueryService);
  private dialogRef = inject(MatDialogRef<TrackEditModalComponent>);
  private toast = inject(ToastService);
  private cdr = inject(ChangeDetectorRef);
  public data = inject<TrackEditModalData>(MAT_DIALOG_DATA);

  public ngOnInit(): void {
    this.initForm();
    this.loadGenres();
  }

  private initForm(): void {
    this.form = this.fb.group({
      title: [this.data.track.title, [zodValidator(TrackUpdateSchema.shape.title)]],
      artist: [this.data.track.artist, [zodValidator(TrackUpdateSchema.shape.artist)]],
      album: [this.data.track.album ?? ''],
      genres: [this.data.track.genres, [zodValidator(TrackUpdateSchema.shape.genres)]],
      coverImage: [this.data.track.coverImage ?? '', [zodValidator(TrackUpdateSchema.shape.coverImage)]]
    });
  }

  private loadGenres(): void {
    // Use computed signal directly - no need for loading state
    this.genres = this.genreQueryService.genreNames();
  }

  public addGenre(event: MatChipInputEvent): void {
    const value = event.value.trim();
    const formValue: unknown = this.form.get('genres')?.value;

    if (isArray<string>(formValue)) {
      const currentGenres = formValue;
      if (value !== '' && !currentGenres.includes(value) && this.genres.includes(value)) {
        this.form.get('genres')?.setValue([...currentGenres, value]);
      }
    }

    event.chipInput.clear();
  }

  public removeGenre(genre: string): void {
    const formValue: unknown = this.form.get('genres')?.value;

    if (isArray<string>(formValue)) {
      const updatedGenres = formValue.filter(g => g !== genre);
      this.form.get('genres')?.setValue(updatedGenres);
    }
  }

  public selectGenre(genre: string): void {
    const formValue: unknown = this.form.get('genres')?.value;

    if (isArray<string>(formValue)) {
      const currentGenres = formValue;
      if (!currentGenres.includes(genre)) {
        this.form.get('genres')?.setValue([...currentGenres, genre]);
      }
    }
  }

  public onSubmit(): void {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }

    this.submitting = true;

    const formData = this.form.value as TrackUpdate;

    this.trackQueryService.updateTrackMutation.mutate(
      { id: this.data.track.id, data: formData },
      {
        onSuccess: (track) => {
          this.submitting = false;
          this.toast.success(`Track "${track.title}" updated successfully`);
          this.dialogRef.close(track);
          this.cdr.markForCheck();
        },
        onError: (error) => {
          this.submitting = false;
          console.error('Failed to update track', error);
          this.toast.error('Failed to update track. Please try again.');
          this.cdr.markForCheck();
        }
      }
    );
  }

  public onCancel(): void {
    this.dialogRef.close();
  }

  public get titleControl(): AbstractControl | null { return this.form.get('title'); }
  public get artistControl(): AbstractControl | null { return this.form.get('artist'); }
  public get albumControl(): AbstractControl | null { return this.form.get('album'); }
  public get genresControl(): AbstractControl | null { return this.form.get('genres'); }
  public get coverImageControl(): AbstractControl | null { return this.form.get('coverImage'); }
}

import { Injectable, inject } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { Observable, map } from 'rxjs';
import { Option, QueryFilters, pipe } from '@app/shared';

export interface TrackFilters {
  search: Option<string>;
  genre: Option<string>;
  artist: Option<string>;
  page: Option<number>;
  limit: Option<number>;
  sortOrder: Option<'asc' | 'desc'>;
}

@Injectable({
  providedIn: 'root'
})
export class QueryParamsService {
  private route = inject(ActivatedRoute);
  private router = inject(Router);

  /**
   * Get all filter parameters from the URL as Option monads
   */
  public getTrackFilters(): Observable<TrackFilters> {
    return this.route.queryParams.pipe(
      map(queryParams => ({
        search: QueryFilters.extractSearchQuery(queryParams),
        genre: QueryFilters.extractGenreFilter(queryParams),
        artist: QueryFilters.extractArtistFilter(queryParams),
        page: QueryFilters.extractPageNumber(queryParams),
        limit: QueryFilters.extractPageSize(queryParams),
        sortOrder: QueryFilters.extractSortOrder(queryParams)
      }))
    );
  }

  /**
   * Update parameters in URL (immutable)
   */
  public updateQueryParams(updates: Partial<Record<string, string | number | null>>): Promise<boolean> {
    return this.router.navigate([], {
      relativeTo: this.route,
      queryParams: updates,
      queryParamsHandling: 'merge'
    });
  }

  /**
   * Clear all settings
   */
  public clearQueryParams(): Promise<boolean> {
    return this.router.navigate([], {
      relativeTo: this.route,
      queryParams: {}
    });
  }

  /**
   * Combine several Option parameters into a filter object
   * Only specific values will be included in the result
   */
  public combineFiltersToParams(filters: TrackFilters): Record<string, string | number> {
    const result: Record<string, string | number> = {};

    Option.match(
      filters.search,
      (search) => { result['search'] = search; },
      () => { /* no-op */ }
    );

    Option.match(
      filters.genre,
      (genre) => { result['genre'] = genre; },
      () => { /* no-op */ }
    );

    Option.match(
      filters.artist,
      (artist) => { result['artist'] = artist; },
      () => { /* no-op */ }
    );

    Option.match(
      filters.page,
      (page) => { result['page'] = page; },
      () => { /* no-op */ }
    );

    Option.match(
      filters.limit,
      (limit) => { result['limit'] = limit; },
      () => { /* no-op */ }
    );

    Option.match(
      filters.sortOrder,
      (order) => { result['order'] = order; },
      () => { /* no-op */ }
    );

    return result;
  }

  /**
   * Create a URL with parameters for an API request
   */
  public createApiParams(filters: TrackFilters): {
    page?: number;
    limit?: number;
    sort?: string;
    order?: 'asc' | 'desc';
    search?: string;
    genre?: string;
    artist?: string;
  } {
    const apiParams: ReturnType<typeof this.createApiParams> = {};

    pipe(
      filters.search,
      Option.map(search => apiParams.search = search)
    );

    pipe(
      filters.genre,
      Option.map(genre => apiParams.genre = genre)
    );

    pipe(
      filters.artist,
      Option.map(artist => apiParams.artist = artist)
    );

    pipe(
      filters.page,
      Option.map(page => apiParams.page = page)
    );

    pipe(
      filters.limit,
      Option.map(limit => apiParams.limit = limit)
    );

    pipe(
      filters.sortOrder,
      Option.map(order => apiParams.order = order)
    );

    return apiParams;
  }
}

import { Injectable, inject, signal, computed } from '@angular/core';
import {
  injectQuery,
  injectMutation,
  QueryClient
} from '@tanstack/angular-query-experimental';
import { lastValueFrom, firstValueFrom } from 'rxjs';
import {
  isDefined,
  QUERY_CACHE_TIMES,
  PAGINATION_DEFAULTS,
  SORT_DEFAULTS
} from '@app/shared';
import {
  Track,
  TrackCreate,
  TrackUpdate,
  PaginatedTracksResponse,
  BulkDeleteResponse
} from './track';
import { TrackGraphQLService } from './track-graphql.service';
import {
  TracksInput,
  TrackSortField,
  SortOrder,
  Track as GQLTrack,
  TrackCreateInput,
  TrackUpdateInput,
} from '@shared/graphql/generated';

// Synchronize with TrackListParams from API service
export interface TrackFilters {
  page?: number;
  limit?: number;
  sort?: string;
  order?: 'asc' | 'desc';
  search?: string;
  genre?: string;
  artist?: string;
  [key: string]: string | number | undefined; // Add index signature
}

@Injectable({
  providedIn: 'root'
})
export class TrackQueryService {
  private trackGraphQL = inject(TrackGraphQLService);
  private queryClient = inject(QueryClient);

  private filtersSignal = signal<TrackFilters>({
    page: PAGINATION_DEFAULTS.DEFAULT_PAGE,
    limit: PAGINATION_DEFAULTS.DEFAULT_LIMIT,
    sort: SORT_DEFAULTS.DEFAULT_SORT_FIELD,
    order: SORT_DEFAULTS.DEFAULT_SORT_ORDER
  });

  private selectedTracksSignal = signal<Set<string>>(new Set());

  // Public readonly signals
  public readonly filters = this.filtersSignal.asReadonly();
  public readonly selectedTracks = this.selectedTracksSignal.asReadonly();

  // Computed values
  public readonly hasSelectedTracks = computed(() =>
    this.selectedTracks().size > 0
  );

  public readonly selectedTrackIds = computed(() =>
    Array.from(this.selectedTracks())
  );

  // Query for fetching tracks
  public readonly tracksQuery = injectQuery(() => ({
    queryKey: ['tracks', this.filters()],
    queryFn: ({ queryKey }) => {
      const [, filters] = queryKey as [string, TrackFilters];
      return this.fetchTracks(filters);
    },
    staleTime: QUERY_CACHE_TIMES.DEFAULT_STALE_TIME,
    gcTime: QUERY_CACHE_TIMES.DEFAULT_GC_TIME,
  }));

  // Computed for convenient data access
  public readonly tracks = computed(() =>
    this.tracksQuery.data()?.data ?? []
  );

  public readonly pagination = computed(() => ({
    page: this.tracksQuery.data()?.meta.page ?? PAGINATION_DEFAULTS.DEFAULT_PAGE,
    limit: this.tracksQuery.data()?.meta.limit ?? PAGINATION_DEFAULTS.DEFAULT_LIMIT,
    total: this.tracksQuery.data()?.meta.total ?? 0,
    totalPages: this.tracksQuery.data()?.meta.totalPages ?? 0
  }));

  public readonly isLoading = computed(() =>
    this.tracksQuery.isPending()
  );

  public readonly error = computed(() =>
    this.tracksQuery.error()
  );

  // Mutation for creating track
  public readonly createTrackMutation = injectMutation(() => ({
    mutationFn: (trackData: TrackCreate) => this.createTrack(trackData),
    onSuccess: () => {
      void this.queryClient.invalidateQueries({ queryKey: ['tracks'] });
    },
  }));

  // Mutation for updating track
  public readonly updateTrackMutation = injectMutation(() => ({
    mutationFn: ({ id, data }: { id: string; data: TrackUpdate }) =>
      this.updateTrack(id, data),
    onSuccess: () => {
      void this.queryClient.invalidateQueries({ queryKey: ['tracks'] });
    },
  }));

  // Mutation for deleting track
  public readonly deleteTrackMutation = injectMutation(() => ({
    mutationFn: (id: string) => this.deleteTrack(id),
    onSuccess: () => {
      void this.queryClient.invalidateQueries({ queryKey: ['tracks'] });
    },
  }));

  // Mutation for bulk deletion
  public readonly bulkDeleteMutation = injectMutation(() => ({
    mutationFn: (ids: string[]) => this.bulkDeleteTracks(ids),
    onSuccess: () => {
      void this.queryClient.invalidateQueries({ queryKey: ['tracks'] });
      this.clearSelection();
    },
  }));

  // Methods for working with filters
  public updateFilters(newFilters: Partial<TrackFilters>): void {
    this.filtersSignal.update(current => ({
      ...current,
      ...newFilters
    }));
  }

  public resetFilters(): void {
    this.filtersSignal.set({
      page: PAGINATION_DEFAULTS.DEFAULT_PAGE,
      limit: PAGINATION_DEFAULTS.DEFAULT_LIMIT,
      sort: SORT_DEFAULTS.DEFAULT_SORT_FIELD,
      order: SORT_DEFAULTS.DEFAULT_SORT_ORDER
    });
  }

  // Methods for working with track selection
  public toggleTrackSelection(trackId: string): void {
    this.selectedTracksSignal.update(current => {
      const newSet = new Set(current);
      if (newSet.has(trackId)) {
        newSet.delete(trackId);
      } else {
        newSet.add(trackId);
      }
      return newSet;
    });
  }

  public selectAllTracks(): void {
    const allTrackIds = this.tracks().map(track => track.id);
    this.selectedTracksSignal.set(new Set(allTrackIds));
  }

  public clearSelection(): void {
    this.selectedTracksSignal.set(new Set());
  }

  public isTrackSelected(trackId: string): boolean {
    return this.selectedTracks().has(trackId);
  }

  // Methods for executing requests
  private async fetchTracks(filters: TrackFilters): Promise<PaginatedTracksResponse> {
    try {
      // Map TrackFilters -> TracksInput (GraphQL)
      const input: TracksInput = {};

      // Pagination
      if (isDefined(filters.page) || isDefined(filters.limit)) {
        input.pagination = {
          page: filters.page ?? null,
          limit: filters.limit ?? null,
        };
      }

      // Filter
      if (isDefined(filters.search) || isDefined(filters.genre) || isDefined(filters.artist)) {
        input.filter = {
          search: filters.search ?? null,
          genre: filters.genre ?? null,
          artist: filters.artist ?? null,
        };
      }

      // Sort
        input.sort = {
        field: isDefined(filters.sort) && filters.sort !== ''
          ? this.normalizeSortField(filters.sort)
          : null,
        order: isDefined(filters.order)
          ? (filters.order.toUpperCase() as SortOrder)
          : null,
        };

      const gqlResult = await firstValueFrom(this.trackGraphQL.getTracks(input));

      return {
        data: gqlResult.data.map(track => this.fromGQLTrack(track)),
        meta: {
          total: gqlResult.pageInfo.total,
          page: gqlResult.pageInfo.page,
          limit: gqlResult.pageInfo.limit,
          totalPages: gqlResult.pageInfo.totalPages
        }
      };
    } catch (error) {
      if (error instanceof Error) throw error;
      throw new Error('Unknown error occurred');
    }
  }

  private async createTrack(trackData: TrackCreate): Promise<Track> {
    try {
      const result = await lastValueFrom(
        this.trackGraphQL.createTrack(this.toCreateInput(trackData)),
      );
      return this.fromGQLTrack(result);
    } catch (error) {
      if (error instanceof Error) throw error;
      throw new Error('Unknown error occurred');
    }
  }

  private async updateTrack(id: string, data: TrackUpdate): Promise<Track> {
    try {
      const result = await lastValueFrom(
        this.trackGraphQL.updateTrack(id, this.toUpdateInput(data)),
      );
      return this.fromGQLTrack(result);
    } catch (error) {
      if (error instanceof Error) throw error;
      throw new Error('Unknown error occurred');
    }
  }

  private async deleteTrack(id: string): Promise<void> {
    try {
      const success = await lastValueFrom(this.trackGraphQL.deleteTrack(id));
      if (!success) throw new Error('Failed to delete track');
      return;
    } catch (error) {
      if (error instanceof Error) throw error;
      throw new Error('Unknown error occurred');
    }
  }

  private async bulkDeleteTracks(ids: string[]): Promise<BulkDeleteResponse> {
    try {
      const res = await lastValueFrom(this.trackGraphQL.deleteTracks(ids));
      return {
        success: res.successIds,
        failed: res.failedIds
      };
    } catch (error) {
      if (error instanceof Error) throw error;
      throw new Error('Unknown error occurred');
    }
  }

  // Methods for working with cache
  public refreshTracks(): void {
    void this.queryClient.invalidateQueries({ queryKey: ['tracks'] });
  }

  public prefetchTracks(filters: TrackFilters): void {
    void this.queryClient.prefetchQuery({
      queryKey: ['tracks', filters],
      queryFn: () => this.fetchTracks(filters),
      staleTime: QUERY_CACHE_TIMES.TRACK_PREFETCH_STALE_TIME,
    });
  }

  // Optimistic updates
  public async optimisticUpdateTrack(id: string, data: TrackUpdate): Promise<void> {
    await this.queryClient.cancelQueries({ queryKey: ['tracks'] });

    const previousData = this.queryClient.getQueryData(['tracks', this.filters()]);

    // Optimistically update cache
