      .toUpperCase(); // created_At -> CREATED_AT

    if ((Object.values(TrackSortField) as string[]).includes(snake)) {
      return snake as TrackSortField;
    }

    // Fallback на CREATED_AT
    return TrackSortField.CreatedAt;
  }
