export type DeleteTrackFileMutationVariables = Exact<{
  id: Scalars['String']['input'];
}>;


export interface DeleteTrackFileMutation { __typename?: 'Mutation', deleteTrackFile: { __typename?: 'Track', id: string, title: string, artist: string, album?: string | null, genres: string[], slug: string, coverImage?: string | null, audioFile?: string | null, createdAt: string, updatedAt: string } }

export type DeleteTrackMutationVariables = Exact<{
  id: Scalars['String']['input'];
}>;


export interface DeleteTrackMutation { __typename?: 'Mutation', deleteTrack: boolean }

export type DeleteTracksMutationVariables = Exact<{
  ids: Scalars['String']['input'][] | Scalars['String']['input'];
}>;


export interface DeleteTracksMutation { __typename?: 'Mutation', deleteTracks: { __typename?: 'BulkDeleteResponse', success: boolean, successIds: string[], failedIds: string[], errors?: { __typename?: 'Error', message: string, code?: string | null, field?: string | null }[] | null } }

export type UpdateTrackMutationVariables = Exact<{
  id: Scalars['String']['input'];
  input: TrackUpdateInput;
}>;


export interface UpdateTrackMutation { __typename?: 'Mutation', updateTrack: { __typename?: 'Track', id: string, title: string, artist: string, album?: string | null, genres: string[], slug: string, coverImage?: string | null, audioFile?: string | null, createdAt: string, updatedAt: string } }

export type UploadTrackFileMutationVariables = Exact<{
  id: Scalars['String']['input'];
  file: Scalars['Upload']['input'];
}>;


export interface UploadTrackFileMutation { __typename?: 'Mutation', uploadTrackFile: { __typename?: 'Track', id: string, title: string, artist: string, album?: string | null, genres: string[], slug: string, coverImage?: string | null, audioFile?: string | null, createdAt: string, updatedAt: string } }

export type GetGenresQueryVariables = Exact<Record<string, never>>;


export interface GetGenresQuery { __typename?: 'Query', genres: { __typename?: 'Genre', id: string, name: string, slug: string }[] }

export type GetTracksQueryVariables = Exact<{
