import { Injectable, inject } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { Observable, map } from 'rxjs';
import { Option, QueryFilters, pipe } from '@app/shared';

export interface TrackFilters {
  search: Option<string>;
  genre: Option<string>;
  artist: Option<string>;
  page: Option<number>;
  limit: Option<number>;
  sortOrder: Option<'asc' | 'desc'>;
}

@Injectable({
  providedIn: 'root'
})
export class QueryParamsService {
  private route = inject(ActivatedRoute);
  private router = inject(Router);

  /**
   * Get all filter parameters from the URL as Option monads
   */
  public getTrackFilters(): Observable<TrackFilters> {
    return this.route.queryParams.pipe(
      map(queryParams => ({
        search: QueryFilters.extractSearchQuery(queryParams),
        genre: QueryFilters.extractGenreFilter(queryParams),
        artist: QueryFilters.extractArtistFilter(queryParams),
        page: QueryFilters.extractPageNumber(queryParams),
        limit: QueryFilters.extractPageSize(queryParams),
        sortOrder: QueryFilters.extractSortOrder(queryParams)
      }))
    );
  }

  /**
   * Update parameters in URL (immutable)
   */
  public updateQueryParams(updates: Partial<Record<string, string | number | null>>): Promise<boolean> {
    return this.router.navigate([], {
      relativeTo: this.route,
      queryParams: updates,
      queryParamsHandling: 'merge'
    });
  }

  /**
   * Clear all settings
   */
  public clearQueryParams(): Promise<boolean> {
    return this.router.navigate([], {
      relativeTo: this.route,
      queryParams: {}
    });
  }

  /**
   * Combine several Option parameters into a filter object
   * Only specific values will be included in the result
   */
  public combineFiltersToParams(filters: TrackFilters): Record<string, string | number> {
    const result: Record<string, string | number> = {};

    Option.match(
      filters.search,
      (search) => { result['search'] = search; },
      () => { /* no-op */ }
    );

    Option.match(
      filters.genre,
      (genre) => { result['genre'] = genre; },
      () => { /* no-op */ }
    );

    Option.match(
      filters.artist,
      (artist) => { result['artist'] = artist; },
      () => { /* no-op */ }
    );

    Option.match(
      filters.page,
      (page) => { result['page'] = page; },
      () => { /* no-op */ }
    );

    Option.match(
      filters.limit,
      (limit) => { result['limit'] = limit; },
      () => { /* no-op */ }
    );

    Option.match(
      filters.sortOrder,
      (order) => { result['order'] = order; },
      () => { /* no-op */ }
    );

    return result;
  }

  /**
   * Create a URL with parameters for an API request
   */
  public createApiParams(filters: TrackFilters): {
    page?: number;
    limit?: number;
    sort?: string;
    order?: 'asc' | 'desc';
    search?: string;
    genre?: string;
    artist?: string;
  } {
    const apiParams: ReturnType<typeof this.createApiParams> = {};

    pipe(
      filters.search,
      Option.map(search => apiParams.search = search)
    );

    pipe(
      filters.genre,
      Option.map(genre => apiParams.genre = genre)
    );

    pipe(
      filters.artist,
      Option.map(artist => apiParams.artist = artist)
    );

    pipe(
      filters.page,
      Option.map(page => apiParams.page = page)
    );

    pipe(
      filters.limit,
      Option.map(limit => apiParams.limit = limit)
    );

    pipe(
      filters.sortOrder,
      Option.map(order => apiParams.order = order)
    );

    return apiParams;
  }
}

import { Injectable, Signal, computed } from '@angular/core';
import { Observable, BehaviorSubject, distinctUntilChanged } from 'rxjs';
import { toObservable } from '@angular/core/rxjs-interop';

/**
 * Adapter for converting Angular Signals to RxJS Observables
 * Provides backward compatibility for components still using RxJS
 */
@Injectable({
  providedIn: 'root'
})
export class SignalToObservableAdapter {
  /**
   * Converts a Signal to Observable
   * @param signal - Angular Signal to convert
   * @returns Observable emitting signal values
   */
  public static toObservable<T>(signal: Signal<T>): Observable<T> {
    return toObservable(signal);
  }

  /**
   * Converts multiple Signals to a map of Observables
   * @param signals - Object with Signal values
   * @returns Object with Observable values
   */
  /* eslint-disable @typescript-eslint/no-explicit-any */
  public static toObservableMap(
    signals: Record<string, Signal<any>>
  ): Record<string, Observable<any>> {
    const result: Record<string, Observable<any>> = {};

    for (const key in signals) {
      if (Object.prototype.hasOwnProperty.call(signals, key)) {
        const signal = signals[key];
        if (signal != null) {
          result[key] = toObservable(signal);
        }
      }
    }

    return result;
  }
  /* eslint-enable @typescript-eslint/no-explicit-any */

  /**
   * Creates Observable from computed Signal
   * Useful for complex calculations that need to be reactive
   * @param computedSignal - Computed Signal to convert
   * @returns Observable with computed values
   */
  public static fromComputed<T>(computedSignal: Signal<T>): Observable<T> {
    return toObservable(computedSignal);
  }

  /**
   * Конвертирует Signal в Observable
   */
  public signalToObservable<T>(signal: Signal<T>): Observable<T> {
    const subject = new BehaviorSubject<T>(signal());

    // Создаем effect для отслеживания изменений signal
    computed(() => {
      const value = signal();
      subject.next(value);
      return value;
    });

    // В реальном приложении нужно будет управлять жизненным циклом effect

    return subject.asObservable().pipe(
      distinctUntilChanged()
    );
  }

  /**
   * Создает Observable из computed signal
   */
  public computedToObservable<T>(computedSignal: Signal<T>): Observable<T> {
    return this.signalToObservable(computedSignal);
  }
}

