import { Injectable, inject, signal, computed } from '@angular/core';
import {
  injectQuery,
  injectMutation,
  QueryClient
} from '@tanstack/angular-query-experimental';
import { lastValueFrom, firstValueFrom } from 'rxjs';
import {
  isDefined,
  QUERY_CACHE_TIMES,
  PAGINATION_DEFAULTS,
  SORT_DEFAULTS
} from '@app/shared';
import {
  Track,
  TrackCreate,
  TrackUpdate,
  PaginatedTracksResponse,
  BulkDeleteResponse
} from './track';
import { TrackGraphQLService } from './track-graphql.service';
import {
  TracksInput,
  TrackSortField,
  SortOrder,
  Track as GQLTrack,
  TrackCreateInput,
  TrackUpdateInput,
} from '@shared/graphql/generated';

// Synchronize with TrackListParams from API service
export interface TrackFilters {
  page?: number;
  limit?: number;
  sort?: string;
  order?: 'asc' | 'desc';
  search?: string;
  genre?: string;
  artist?: string;
  [key: string]: string | number | undefined; // Add index signature
}

@Injectable({
  providedIn: 'root'
})
export class TrackQueryService {
  private trackGraphQL = inject(TrackGraphQLService);
  private queryClient = inject(QueryClient);

  private filtersSignal = signal<TrackFilters>({
    page: PAGINATION_DEFAULTS.DEFAULT_PAGE,
    limit: PAGINATION_DEFAULTS.DEFAULT_LIMIT,
    sort: SORT_DEFAULTS.DEFAULT_SORT_FIELD,
    order: SORT_DEFAULTS.DEFAULT_SORT_ORDER
  });

  private selectedTracksSignal = signal<Set<string>>(new Set());

  // Public readonly signals
  public readonly filters = this.filtersSignal.asReadonly();
  public readonly selectedTracks = this.selectedTracksSignal.asReadonly();

  // Computed values
  public readonly hasSelectedTracks = computed(() =>
    this.selectedTracks().size > 0
  );

  public readonly selectedTrackIds = computed(() =>
    Array.from(this.selectedTracks())
  );

  // Query for fetching tracks
  public readonly tracksQuery = injectQuery(() => ({
    queryKey: ['tracks', this.filters()],
    queryFn: ({ queryKey }) => {
      const [, filters] = queryKey as [string, TrackFilters];
      return this.fetchTracks(filters);
    },
    staleTime: QUERY_CACHE_TIMES.DEFAULT_STALE_TIME,
    gcTime: QUERY_CACHE_TIMES.DEFAULT_GC_TIME,
  }));

  // Computed for convenient data access
  public readonly tracks = computed(() =>
    this.tracksQuery.data()?.data ?? []
  );

  public readonly pagination = computed(() => ({
    page: this.tracksQuery.data()?.meta.page ?? PAGINATION_DEFAULTS.DEFAULT_PAGE,
    limit: this.tracksQuery.data()?.meta.limit ?? PAGINATION_DEFAULTS.DEFAULT_LIMIT,
    total: this.tracksQuery.data()?.meta.total ?? 0,
    totalPages: this.tracksQuery.data()?.meta.totalPages ?? 0
  }));

  public readonly isLoading = computed(() =>
    this.tracksQuery.isPending()
  );

  public readonly error = computed(() =>
    this.tracksQuery.error()
  );

  // Mutation for creating track
  public readonly createTrackMutation = injectMutation(() => ({
    mutationFn: (trackData: TrackCreate) => this.createTrack(trackData),
    onSuccess: () => {
      void this.queryClient.invalidateQueries({ queryKey: ['tracks'] });
    },
  }));

  // Mutation for updating track
  public readonly updateTrackMutation = injectMutation(() => ({
    mutationFn: ({ id, data }: { id: string; data: TrackUpdate }) =>
      this.updateTrack(id, data),
    onSuccess: () => {
      void this.queryClient.invalidateQueries({ queryKey: ['tracks'] });
    },
  }));

  // Mutation for deleting track
  public readonly deleteTrackMutation = injectMutation(() => ({
    mutationFn: (id: string) => this.deleteTrack(id),
    onSuccess: () => {
      void this.queryClient.invalidateQueries({ queryKey: ['tracks'] });
    },
  }));

  // Mutation for bulk deletion
  public readonly bulkDeleteMutation = injectMutation(() => ({
    mutationFn: (ids: string[]) => this.bulkDeleteTracks(ids),
    onSuccess: () => {
      void this.queryClient.invalidateQueries({ queryKey: ['tracks'] });
      this.clearSelection();
    },
  }));

  // Methods for working with filters
  public updateFilters(newFilters: Partial<TrackFilters>): void {
    this.filtersSignal.update(current => ({
      ...current,
      ...newFilters
    }));
  }

  public resetFilters(): void {
    this.filtersSignal.set({
      page: PAGINATION_DEFAULTS.DEFAULT_PAGE,
      limit: PAGINATION_DEFAULTS.DEFAULT_LIMIT,
      sort: SORT_DEFAULTS.DEFAULT_SORT_FIELD,
      order: SORT_DEFAULTS.DEFAULT_SORT_ORDER
    });
  }

  // Methods for working with track selection
  public toggleTrackSelection(trackId: string): void {
    this.selectedTracksSignal.update(current => {
      const newSet = new Set(current);
      if (newSet.has(trackId)) {
        newSet.delete(trackId);
      } else {
        newSet.add(trackId);
      }
      return newSet;
    });
  }

  public selectAllTracks(): void {
    const allTrackIds = this.tracks().map(track => track.id);
    this.selectedTracksSignal.set(new Set(allTrackIds));
  }

  public clearSelection(): void {
    this.selectedTracksSignal.set(new Set());
  }

  public isTrackSelected(trackId: string): boolean {
    return this.selectedTracks().has(trackId);
  }

  // Methods for executing requests
  private async fetchTracks(filters: TrackFilters): Promise<PaginatedTracksResponse> {
    try {
      // Map TrackFilters -> TracksInput (GraphQL)
      const input: TracksInput = {};

      // Pagination
      if (isDefined(filters.page) || isDefined(filters.limit)) {
        input.pagination = {
          page: filters.page ?? null,
          limit: filters.limit ?? null,
        };
      }

      // Filter
      if (isDefined(filters.search) || isDefined(filters.genre) || isDefined(filters.artist)) {
        input.filter = {
          search: filters.search ?? null,
          genre: filters.genre ?? null,
          artist: filters.artist ?? null,
        };
      }

      // Sort
        input.sort = {
        field: isDefined(filters.sort) && filters.sort !== ''
          ? this.normalizeSortField(filters.sort)
          : null,
        order: isDefined(filters.order)
          ? (filters.order.toUpperCase() as SortOrder)
          : null,
        };

      const gqlResult = await firstValueFrom(this.trackGraphQL.getTracks(input));

      return {
        data: gqlResult.data.map(track => this.fromGQLTrack(track)),
        meta: {
          total: gqlResult.pageInfo.total,
          page: gqlResult.pageInfo.page,
          limit: gqlResult.pageInfo.limit,
          totalPages: gqlResult.pageInfo.totalPages
        }
      };
    } catch (error) {
      if (error instanceof Error) throw error;
      throw new Error('Unknown error occurred');
    }
  }

  private async createTrack(trackData: TrackCreate): Promise<Track> {
    try {
      const result = await lastValueFrom(
        this.trackGraphQL.createTrack(this.toCreateInput(trackData)),
      );
      return this.fromGQLTrack(result);
    } catch (error) {
      if (error instanceof Error) throw error;
      throw new Error('Unknown error occurred');
    }
  }

  private async updateTrack(id: string, data: TrackUpdate): Promise<Track> {
    try {
      const result = await lastValueFrom(
        this.trackGraphQL.updateTrack(id, this.toUpdateInput(data)),
      );
      return this.fromGQLTrack(result);
    } catch (error) {
      if (error instanceof Error) throw error;
      throw new Error('Unknown error occurred');
    }
  }

  private async deleteTrack(id: string): Promise<void> {
    try {
      const success = await lastValueFrom(this.trackGraphQL.deleteTrack(id));
      if (!success) throw new Error('Failed to delete track');
      return;
    } catch (error) {
      if (error instanceof Error) throw error;
      throw new Error('Unknown error occurred');
    }
  }

  private async bulkDeleteTracks(ids: string[]): Promise<BulkDeleteResponse> {
    try {
      const res = await lastValueFrom(this.trackGraphQL.deleteTracks(ids));
      return {
        success: res.successIds,
        failed: res.failedIds
      };
    } catch (error) {
      if (error instanceof Error) throw error;
      throw new Error('Unknown error occurred');
    }
  }

  // Methods for working with cache
  public refreshTracks(): void {
    void this.queryClient.invalidateQueries({ queryKey: ['tracks'] });
  }

  public prefetchTracks(filters: TrackFilters): void {
    void this.queryClient.prefetchQuery({
      queryKey: ['tracks', filters],
      queryFn: () => this.fetchTracks(filters),
      staleTime: QUERY_CACHE_TIMES.TRACK_PREFETCH_STALE_TIME,
    });
  }

  // Optimistic updates
  public async optimisticUpdateTrack(id: string, data: TrackUpdate): Promise<void> {
    await this.queryClient.cancelQueries({ queryKey: ['tracks'] });

    const previousData = this.queryClient.getQueryData(['tracks', this.filters()]);

    // Optimistically update cache
    this.queryClient.setQueryData(['tracks', this.filters()], (old: PaginatedTracksResponse | undefined) => {
      if (old == null) return old;

      return {
        ...old,
        data: old.data.map(track =>
          track.id === id ? { ...track, ...data } : track
        )
      };
    });

    try {
      await this.updateTrackMutation.mutateAsync({ id, data });
    } catch (error: unknown) {
      // Rollback changes on error
      this.queryClient.setQueryData(['tracks', this.filters()], previousData);
      throw error;
    }
  }

  // File upload methods
  public async uploadFile(id: string, file: File): Promise<Track> {
    try {
      const gqlTrack = await lastValueFrom(this.trackGraphQL.uploadFile(id, file));
      const track = this.fromGQLTrack(gqlTrack);
      void this.queryClient.invalidateQueries({ queryKey: ['tracks'] });
      return track;
    } catch (error: unknown) {
      if (error instanceof Error) {
        throw error;
      }
      throw new Error('Unknown error occurred');
    }
  }

  public async deleteFile(id: string): Promise<Track> {
    try {
      const gqlTrack = await lastValueFrom(this.trackGraphQL.deleteFile(id));
      const track = this.fromGQLTrack(gqlTrack);
      void this.queryClient.invalidateQueries({ queryKey: ['tracks'] });
      return track;
    } catch (error: unknown) {
      if (error instanceof Error) {
        throw error;
      }
      throw new Error('Unknown error occurred');
    }
  }

  // -------------------- Mapping helpers --------------------

  /** Map domain TrackCreate -> GraphQL TrackCreateInput */
  private toCreateInput(data: TrackCreate): TrackCreateInput {
    return {
      artist: data.artist,
      title: data.title,
      genres: data.genres,
      album: data.album ?? null,
      coverImage: data.coverImage ?? null,
    };
  }

  /** Map domain TrackUpdate -> GraphQL TrackUpdateInput */
  private toUpdateInput(data: TrackUpdate): TrackUpdateInput {
    return {
      artist: data.artist ?? null,
      title: data.title ?? null,
      genres: data.genres ?? null,
      album: data.album ?? null,
      coverImage: data.coverImage ?? null,
    };
  }

  /** Map GraphQL Track -> domain Track (convert nulls to undefined) */
  private fromGQLTrack(track: GQLTrack): Track {
    return {
      id: track.id,
      title: track.title,
      artist: track.artist,
      album: track.album ?? undefined,
      genres: track.genres,
      slug: track.slug,
      coverImage: track.coverImage ?? undefined,
      audioFile: track.audioFile ?? undefined,
      createdAt: track.createdAt,
      updatedAt: track.updatedAt,
    };
  }

  /** Convert frontend field (camelCase) to GraphQL enum (SNAKE_UPPER) */
  private normalizeSortField(field: string): TrackSortField {
    const snake = field
      .replace(/([a-z])([A-Z])/g, '$1_$2') // createdAt -> created_At
      .toUpperCase(); // created_At -> CREATED_AT

    if ((Object.values(TrackSortField) as string[]).includes(snake)) {
      return snake as TrackSortField;
    }

    // Fallback на CREATED_AT
    return TrackSortField.CreatedAt;
  }
}

import { inject, Injectable } from '@angular/core';
import { BehaviorSubject, Observable, map, catchError, of } from 'rxjs';
import { isDefined, Result } from '@app/shared/lib';
import { ValidatedTrackApiService } from '@app/shared/api';
import { TrackErrors, TrackError } from '@app/shared/lib/application-error';
import { BulkDeleteResponse, PaginatedTracksResponse, Track, TrackCreate, TrackUpdate } from './track';

@Injectable({
  providedIn: 'root'
})
export class TrackService {
  private tracksCache = new BehaviorSubject<Track[]>([]);

  private trackApi = inject(ValidatedTrackApiService);

  public getTracks(params: {
    page?: number;
    limit?: number;
    sort?: string;
    order?: 'asc' | 'desc';
    search?: string;
    genre?: string;
    artist?: string;
  }): Observable<Result<PaginatedTracksResponse, TrackError>> {
    const { page, limit, sort, order, search, genre, artist } = params;
    const filteredParams: typeof params = {};

    if (isDefined(page)) filteredParams.page = page;
    if (isDefined(limit)) filteredParams.limit = limit;
    if (isDefined(sort)) filteredParams.sort = sort;
    if (isDefined(order)) filteredParams.order = order;
    if (isDefined(search)) filteredParams.search = search;
    if (isDefined(genre)) filteredParams.genre = genre;
    if (isDefined(artist)) filteredParams.artist = artist;

    return this.trackApi.getAll(filteredParams).pipe(
      map(apiResult => Result.match(
        apiResult,
        (response: PaginatedTracksResponse) => {
          this.tracksCache.next(response.data);
          return Result.Ok(response) as Result<PaginatedTracksResponse, TrackError>;
        },
        () => Result.Error(TrackErrors.fetchError(
          'Failed to fetch tracks',
          { params: filteredParams }
        )) as Result<PaginatedTracksResponse, TrackError>
      )),
      catchError(error => of(Result.Error(TrackErrors.fetchError(
        'Network error while fetching tracks',
        { error, params: filteredParams }
      ))))
    );
  }

  public getTrack(slug: string): Observable<Result<Track, TrackError>> {
    return this.trackApi.getBySlug(slug).pipe(
      map(apiResult => Result.match(
        apiResult,
        (track: Track) => Result.Ok(track) as Result<Track, TrackError>,
        () => Result.Error(TrackErrors.notFoundError(slug)) as Result<Track, TrackError>
      )),
      catchError(error => of(Result.Error(TrackErrors.fetchError(
        `Network error while fetching track with slug: ${slug}`,
        { error, slug }
      ))))
    );
  }

  public createTrack(data: TrackCreate): Observable<Result<Track, TrackError>> {
    const tempId = `temp-${String(Date.now())}`;

    const optimisticTrack: Track = {
      id: tempId,
      title: data.title,
      artist: data.artist,
      album: data.album ?? undefined,
      genres: data.genres,
      slug: this.generateSlug(data.title, tempId),
      coverImage: data.coverImage,
      audioFile: undefined,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };

    const currentTracks = this.tracksCache.getValue();
    this.tracksCache.next([optimisticTrack, ...currentTracks]);

    return this.trackApi.createTrack(data).pipe(
      map(apiResult => Result.match(
        apiResult,
        (createdTrack: Track) => {
          const updatedTracks = this.tracksCache.getValue().map(t =>
            t.id === tempId ? createdTrack : t
          );
          this.tracksCache.next(updatedTracks);
          return Result.Ok(createdTrack) as Result<Track, TrackError>;
        },
        () => {
          const revertedTracks = this.tracksCache.getValue().filter(t => t.id !== tempId);
          this.tracksCache.next(revertedTracks);
          return Result.Error(TrackErrors.createError(
            'Failed to create track',
            { data, tempId }
          )) as Result<Track, TrackError>;
        }
      )),
      catchError(error => {
        const revertedTracks = this.tracksCache.getValue().filter(t => t.id !== tempId);
        this.tracksCache.next(revertedTracks);
        return of(Result.Error(TrackErrors.createError(
          'Network error while creating track',
          { error, data, tempId }
        )));
      })
    );
  }

  public updateTrack(id: string, data: TrackUpdate): Observable<Result<Track, TrackError>> {
    const currentTracks = this.tracksCache.getValue();
    const trackToUpdate = currentTracks.find(t => t.id === id);

    if (trackToUpdate === undefined) {
      return this.trackApi.updateTrack(id, data).pipe(
        map(apiResult => Result.match(
          apiResult,
          (track: Track) => Result.Ok(track) as Result<Track, TrackError>,
          () => Result.Error(TrackErrors.notFoundError(id)) as Result<Track, TrackError>
        )),
        catchError(error => of(Result.Error(TrackErrors.updateError(
          `Network error while updating track with id: ${id}`,
          { error, id, data }
        ))))
      );
    }

    const { title, genres, artist, coverImage, album } = data;

    const optimisticTrack: Track = {
      ...trackToUpdate,
      ...(isDefined(title) && { title }),
      ...(isDefined(artist) && { artist }),
      ...(isDefined(album) && { album }),
      ...(isDefined(genres) && { genres }),
      ...(isDefined(coverImage) && { coverImage }),
      updatedAt: new Date().toISOString()
    };

    const updatedTracks = currentTracks.map(t =>
      t.id === id ? optimisticTrack : t
    );
    this.tracksCache.next(updatedTracks);

    return this.trackApi.updateTrack(id, data).pipe(
      map(apiResult => Result.match(
        apiResult,
        (updatedTrack: Track) => {
          const serverUpdatedTracks = this.tracksCache.getValue().map(t =>
            t.id === id ? updatedTrack : t
          );
          this.tracksCache.next(serverUpdatedTracks);
          return Result.Ok(updatedTrack) as Result<Track, TrackError>;
        },
        () => {
          this.tracksCache.next(currentTracks);
          return Result.Error(TrackErrors.updateError(
            'Failed to update track',
            { id, data }
          )) as Result<Track, TrackError>;
        }
      )),
      catchError(error => {
        this.tracksCache.next(currentTracks);
        return of(Result.Error(TrackErrors.updateError(
          'Network error while updating track',
          { error, id, data }
        )));
      })
    );
  }

  public deleteTrack(id: string): Observable<Result<null, TrackError>> {
    const currentTracks = this.tracksCache.getValue();

    const updatedTracks = currentTracks.filter(t => t.id !== id);
    this.tracksCache.next(updatedTracks);

    return this.trackApi.deleteTrack(id).pipe(
      map(apiResult => Result.match(
        apiResult,
        () => Result.Ok(null) as Result<null, TrackError>,
        () => {
          this.tracksCache.next(currentTracks);
          return Result.Error(TrackErrors.deleteError(
            'Failed to delete track',
            { id }
          )) as Result<null, TrackError>;
        }
      )),
      catchError(error => {
        this.tracksCache.next(currentTracks);
        return of(Result.Error(TrackErrors.deleteError(
          'Network error while deleting track',
          { error, id }
        )));
      })
    );
  }

  public deleteTracks(ids: string[]): Observable<Result<BulkDeleteResponse, TrackError>> {
    const currentTracks = this.tracksCache.getValue();

    const updatedTracks = currentTracks.filter(t => !ids.includes(t.id));
    this.tracksCache.next(updatedTracks);

    return this.trackApi.deleteMany(ids).pipe(
      map(apiResult => Result.match(
        apiResult,
        (response: BulkDeleteResponse) => {
          if (response.failed.length > 0) {
            const successfullyDeletedIds = response.success;
            const accurateTracks = currentTracks.filter(t => !successfullyDeletedIds.includes(t.id));
            this.tracksCache.next(accurateTracks);
          }
          return Result.Ok(response) as Result<BulkDeleteResponse, TrackError>;
        },
        () => {
          this.tracksCache.next(currentTracks);
          return Result.Error(TrackErrors.deleteError(
            'Failed to delete tracks',
            { ids, count: ids.length }
          )) as Result<BulkDeleteResponse, TrackError>;
        }
      )),
      catchError(error => {
        this.tracksCache.next(currentTracks);
        return of(Result.Error(TrackErrors.deleteError(
          'Network error while deleting tracks',
          { error, ids, count: ids.length }
        )));
      })
    );
  }

  public uploadFile(id: string, file: File): Observable<Result<Track, TrackError>> {
    const currentTracks = this.tracksCache.getValue();
    const trackToUpdate = currentTracks.find(t => t.id === id);

    if (trackToUpdate === undefined) {
      return this.trackApi.uploadFile(id, file).pipe(
        map(apiResult => Result.match(
          apiResult,
          (track: Track) => Result.Ok(track) as Result<Track, TrackError>,
          () => Result.Error(TrackErrors.notFoundError(id)) as Result<Track, TrackError>
        )),
        catchError(error => of(Result.Error(TrackErrors.uploadError(
          `Network error while uploading file for track with id: ${id}`,
          { error, id, fileName: file.name }
        ))))
      );
    }

    const optimisticFileName = file.name;

    const optimisticTrack: Track = {
      ...trackToUpdate,
      audioFile: optimisticFileName,
      updatedAt: new Date().toISOString()
    };

    const updatedTracks = currentTracks.map(t =>
      t.id === id ? optimisticTrack : t
    );
    this.tracksCache.next(updatedTracks);

    return this.trackApi.uploadFile(id, file).pipe(
      map(apiResult => Result.match(
        apiResult,
        (updatedTrack: Track) => {
          const serverUpdatedTracks = this.tracksCache.getValue().map(t =>
            t.id === id ? updatedTrack : t
          );
          this.tracksCache.next(serverUpdatedTracks);
          return Result.Ok(updatedTrack) as Result<Track, TrackError>;
        },
        () => {
          this.tracksCache.next(currentTracks);
          return Result.Error(TrackErrors.uploadError(
            'Failed to upload file',
            { id, fileName: file.name }
          )) as Result<Track, TrackError>;
        }
      )),
      catchError(error => {
        this.tracksCache.next(currentTracks);
        return of(Result.Error(TrackErrors.uploadError(
          'Network error while uploading file',
          { error, id, fileName: file.name }
        )));
      })
    );
  }

  public deleteFile(id: string): Observable<Result<Track, TrackError>> {
    const currentTracks = this.tracksCache.getValue();
    const trackToUpdate = currentTracks.find(t => t.id === id);

    if (trackToUpdate === undefined) {
      return this.trackApi.deleteFile(id).pipe(
        map(apiResult => Result.match(
          apiResult,
          (track: Track) => Result.Ok(track) as Result<Track, TrackError>,
          () => Result.Error(TrackErrors.notFoundError(id)) as Result<Track, TrackError>
        )),
        catchError(error => of(Result.Error(TrackErrors.deleteError(
          `Network error while deleting file for track with id: ${id}`,
          { error, id }
        ))))
      );
    }

    const optimisticTrack: Track = {
      ...trackToUpdate,
      audioFile: undefined,
      updatedAt: new Date().toISOString()
    };

    const updatedTracks = currentTracks.map(t =>
      t.id === id ? optimisticTrack : t
    );
    this.tracksCache.next(updatedTracks);

    return this.trackApi.deleteFile(id).pipe(
      map(apiResult => Result.match(
        apiResult,
        (updatedTrack: Track) => {
          const serverUpdatedTracks = this.tracksCache.getValue().map(t =>
            t.id === id ? updatedTrack : t
          );
          this.tracksCache.next(serverUpdatedTracks);
          return Result.Ok(updatedTrack) as Result<Track, TrackError>;
        },
        () => {
          this.tracksCache.next(currentTracks);
          return Result.Error(TrackErrors.deleteError(
            'Failed to delete file',
            { id }
          )) as Result<Track, TrackError>;
        }
      )),
      catchError(error => {
        this.tracksCache.next(currentTracks);
        return of(Result.Error(TrackErrors.deleteError(
          'Network error while deleting file',
          { error, id }
        )));
      })
    );
  }

  public getTracksCache(): Observable<Track[]> {
    return this.tracksCache.asObservable();
  }

  private generateSlug(title: string, id: string): string {
    return title
        .toLowerCase()
        .replace(/[^a-z0-9\s]/gi, '') // Only allow letters, numbers, and spaces
        .replace(/\s+/g, '-') +        // Replace spaces with dashes
      '-' + id.substring(0, 8);
  }
}

import { gql } from 'apollo-angular';
import { Injectable } from '@angular/core';
import * as Apollo from 'apollo-angular';
export type Maybe<T> = T | null;
export type InputMaybe<T> = Maybe<T>;
export type Exact<T extends Record<string, unknown>> = { [K in keyof T]: T[K] };
export type MakeOptional<T, K extends keyof T> = Omit<T, K> & { [SubKey in K]?: Maybe<T[SubKey]> };
export type MakeMaybe<T, K extends keyof T> = Omit<T, K> & { [SubKey in K]: Maybe<T[SubKey]> };
export type MakeEmpty<T extends Record<string, unknown>, K extends keyof T> = Partial<Record<K, never>>;
export type Incremental<T> = T | { [P in keyof T]?: P extends ' $fragmentName' | '__typename' ? T[P] : never };
/** All built-in and custom scalars, mapped to their actual values */
export interface Scalars {
  ID: { input: string; output: string; }
  String: { input: string; output: string; }
  Boolean: { input: boolean; output: boolean; }
  Int: { input: number; output: number; }
  Float: { input: number; output: number; }
  DateTime: { input: string; output: string; }
  Upload: { input: File | Blob; output: File | Blob; }
}

export interface ActiveTrack {
  __typename?: 'ActiveTrack';
  artist: Scalars['String']['output'];
  audioFile?: Maybe<Scalars['String']['output']>;
  id: Scalars['ID']['output'];
  title: Scalars['String']['output'];
}

export interface BulkDeleteResponse {
  __typename?: 'BulkDeleteResponse';
  errors?: Maybe<Error[]>;
  failedIds: Scalars['String']['output'][];
  success: Scalars['Boolean']['output'];
  successIds: Scalars['String']['output'][];
}

export interface Error {
  __typename?: 'Error';
  code?: Maybe<Scalars['String']['output']>;
  field?: Maybe<Scalars['String']['output']>;
  message: Scalars['String']['output'];
}

export interface Genre {
  __typename?: 'Genre';
  createdAt: Scalars['String']['output'];
  id: Scalars['String']['output'];
  name: Scalars['String']['output'];
  slug: Scalars['String']['output'];
  updatedAt: Scalars['String']['output'];
}

export interface Mutation {
  __typename?: 'Mutation';
  createTrack: Track;
  deleteTrack: Scalars['Boolean']['output'];
  deleteTrackFile: Track;
  deleteTracks: BulkDeleteResponse;
  updateTrack: Track;
  uploadTrackFile: Track;
}


export interface MutationCreateTrackArgs {
  input: TrackCreateInput;
}


export interface MutationDeleteTrackArgs {
  id: Scalars['String']['input'];
}


export interface MutationDeleteTrackFileArgs {
  id: Scalars['String']['input'];
}


export interface MutationDeleteTracksArgs {
  ids: Scalars['String']['input'][];
}


export interface MutationUpdateTrackArgs {
  id: Scalars['String']['input'];
  input: TrackUpdateInput;
}


export interface MutationUploadTrackFileArgs {
  file: Scalars['Upload']['input'];
  id: Scalars['String']['input'];
}

export interface PageInfo {
  __typename?: 'PageInfo';
  limit: Scalars['Int']['output'];
  page: Scalars['Int']['output'];
  total: Scalars['Int']['output'];
  totalPages: Scalars['Int']['output'];
}

export interface PaginationInput {
  limit?: InputMaybe<Scalars['Int']['input']>;
  page?: InputMaybe<Scalars['Int']['input']>;
}

export interface Query {
  __typename?: 'Query';
  genre?: Maybe<Genre>;
  genreBySlug?: Maybe<Genre>;
  genres: Genre[];
  track?: Maybe<Track>;
  trackBySlug?: Maybe<Track>;
  tracks: TracksConnection;
}


export interface QueryGenreArgs {
  id: Scalars['String']['input'];
}


export interface QueryGenreBySlugArgs {
  slug: Scalars['String']['input'];
}


export interface QueryTrackArgs {
  id: Scalars['String']['input'];
}


export interface QueryTrackBySlugArgs {
  slug: Scalars['String']['input'];
}


export interface QueryTracksArgs {
  input?: InputMaybe<TracksInput>;
}

export enum SortOrder {
  Asc = 'ASC',
  Desc = 'DESC'
}

export interface Subscription {
  __typename?: 'Subscription';
  activeTrack?: Maybe<ActiveTrack>;
}

export interface Track {
  __typename?: 'Track';
  album?: Maybe<Scalars['String']['output']>;
  artist: Scalars['String']['output'];
  audioFile?: Maybe<Scalars['String']['output']>;
  coverImage?: Maybe<Scalars['String']['output']>;
  createdAt: Scalars['String']['output'];
  genres: Scalars['String']['output'][];
  id: Scalars['String']['output'];
  slug: Scalars['String']['output'];
  title: Scalars['String']['output'];
  updatedAt: Scalars['String']['output'];
}

export interface TrackCreateInput {
  album?: InputMaybe<Scalars['String']['input']>;
  artist: Scalars['String']['input'];
  coverImage?: InputMaybe<Scalars['String']['input']>;
  genres: Scalars['String']['input'][];
  title: Scalars['String']['input'];
}

export enum TrackSortField {
  Album = 'ALBUM',
  Artist = 'ARTIST',
  CreatedAt = 'CREATED_AT',
  Title = 'TITLE',
  UpdatedAt = 'UPDATED_AT'
}

export interface TrackUpdateInput {
  album?: InputMaybe<Scalars['String']['input']>;
  artist?: InputMaybe<Scalars['String']['input']>;
  coverImage?: InputMaybe<Scalars['String']['input']>;
  genres?: InputMaybe<Scalars['String']['input'][]>;
  title?: InputMaybe<Scalars['String']['input']>;
}

export interface TracksConnection {
  __typename?: 'TracksConnection';
  data: Track[];
  pageInfo: PageInfo;
}

export interface TracksFilterInput {
  artist?: InputMaybe<Scalars['String']['input']>;
  genre?: InputMaybe<Scalars['String']['input']>;
  search?: InputMaybe<Scalars['String']['input']>;
}

