import { Component, Input, Output, EventEmitter, ChangeDetectionStrategy } from '@angular/core';
import { CommonModule } from '@angular/common';

export type ButtonVariant = 'filled' | 'outlined' | 'text' | 'elevated' | 'tonal';
export type ButtonSize = 'small' | 'medium' | 'large';

/**
 * Material 3 Button component
 * 
 * Implements Material 3 design system for buttons
 * Supports various variants: filled, outlined, text, elevated, tonal
 */
@Component({
  selector: 'app-m3-button',
  standalone: true,
  imports: [CommonModule],
  template: `
    <button 
      [class]="buttonClasses"
      [disabled]="disabled"
      [type]="type"
      (click)="onClick($event)"
      [attr.aria-label]="ariaLabel"
      [attr.data-testid]="testId"
    >
      <ng-container *ngIf="loading; else contentTemplate">
        <span class="loading-indicator" aria-hidden="true"></span>
        <span class="sr-only">Loading...</span>
      </ng-container>
      
      <ng-template #contentTemplate>
        <ng-content></ng-content>
      </ng-template>
    </button>
  `,
  styleUrl: './button.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ButtonComponent {
  @Input() variant: ButtonVariant = 'filled';
  @Input() size: ButtonSize = 'medium';
  @Input() disabled = false;
  @Input() loading = false;
  @Input() type: 'button' | 'submit' | 'reset' = 'button';
  @Input() ariaLabel?: string;
  @Input() testId?: string;
  @Input() fullWidth = false;

  @Output() clicked = new EventEmitter<Event>();

  get buttonClasses(): string {
    const classes = [
      'btn',
      `btn--${this.variant}`,
      `btn--${this.size}`,
    ];

    if (this.disabled) classes.push('btn--disabled');
    if (this.loading) classes.push('btn--loading');
    if (this.fullWidth) classes.push('btn--full-width');

    return classes.join(' ');
  }

  onClick(event: Event): void {
    if (!this.disabled && !this.loading) {
      this.clicked.emit(event);
    }
  }
}

import { Component, Input, ChangeDetectionStrategy } from '@angular/core';
import { CommonModule } from '@angular/common';

export type CardVariant = 'filled' | 'outlined' | 'elevated';

/**
 * Material 3 Card component
 * 
 * Implements Material 3 design system for cards
 * Supports various variants: filled, outlined, elevated
 */
@Component({
  selector: 'app-m3-card',
  standalone: true,
  imports: [CommonModule],
  template: `
    <div [class]="cardClasses" [attr.data-testid]="testId">
      <!-- Card header -->
      <div *ngIf="hasHeader" class="card-header">
        <ng-content select="[slot=header]"></ng-content>
      </div>
      
      <!-- Media content -->
      <div *ngIf="hasMedia" class="card-media">
        <ng-content select="[slot=media]"></ng-content>
      </div>
      
      <!-- Main content -->
      <div *ngIf="hasContent" class="card-content">
        <ng-content></ng-content>
      </div>
      
      <!-- Actions -->
      <div *ngIf="hasActions" class="card-actions">
        <ng-content select="[slot=actions]"></ng-content>
      </div>
    </div>
  `,
  styleUrl: './card.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class CardComponent {
  @Input() variant: CardVariant = 'filled';
  @Input() clickable = false;
  @Input() disabled = false;
  @Input() testId?: string;
  @Input() hasHeader = false;
  @Input() hasMedia = false;
  @Input() hasContent = true;
  @Input() hasActions = false;

  get cardClasses(): string {
    const classes = [
      'card',
      `card--${this.variant}`,
    ];

    if (this.clickable) classes.push('card--clickable');
    if (this.disabled) classes.push('card--disabled');

    return classes.join(' ');
  }
}

