import {
  ChangeDetectionStrategy,
  Component,
  DestroyRef,
  inject,
  OnInit,
  computed,
  signal,
  effect
} from '@angular/core';
import { NgForOf, NgIf } from '@angular/common';
import { debounceTime, distinctUntilChanged, Subject } from 'rxjs';
import { MatDialog } from '@angular/material/dialog';
import { MatSnackBar } from '@angular/material/snack-bar';
import { MatPaginator, PageEvent } from '@angular/material/paginator';
import { MatIcon } from '@angular/material/icon';
import { MatFormField, MatLabel } from '@angular/material/form-field';
import { MatInput } from '@angular/material/input';
import { MatOption, MatSelect } from '@angular/material/select';
import { MatButton, MatIconButton } from '@angular/material/button';
import { MatProgressSpinner } from '@angular/material/progress-spinner';
import { MatSelectChange } from '@angular/material/select';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';

import {
  GenreQueryService,
  Track,
  TrackCardComponent,
  TrackPlayerComponent,
  TrackQueryService,
  TrackFilters
} from '@app/entities';
import { TestIdDirective, isDefined, UI_TIMING, MODAL_DIMENSIONS, LazyModalService } from '@app/shared';
import { AudioPlaybackService } from '@app/processes';

@Component({
  selector: 'app-track-list-widget-signals',
  standalone: true,
  imports: [
    TrackCardComponent,
    TrackPlayerComponent,
    TestIdDirective,
    NgIf,
    NgForOf,
    MatIcon,
    MatFormField,
    MatInput,
    MatSelect,
    MatOption,
    MatLabel,
    MatIconButton,
    MatButton,
    MatProgressSpinner,
    MatPaginator,
  ],
  templateUrl: './track-list-widget.component.html',
  styleUrl: './track-list-widget.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class TrackListWidgetSignalsComponent implements OnInit {
  private trackQueryService = inject(TrackQueryService);
  private genreQueryService = inject(GenreQueryService);
  private audioService = inject(AudioPlaybackService);
  private dialog = inject(MatDialog);
  private snackBar = inject(MatSnackBar);
  private destroyRef = inject(DestroyRef);
  private lazyModalService = inject(LazyModalService);

  // Local signals for UI state
  private searchTextSignal = signal<string>('');
  private selectedGenreSignal = signal<string>('');
  private selectedArtistSignal = signal<string>('');
  private selectModeSignal = signal<boolean>(false);
  private submittingSignal = signal<boolean>(false);

  // Public readonly signals
  public readonly searchText = this.searchTextSignal.asReadonly();
  public readonly selectedGenre = this.selectedGenreSignal.asReadonly();
  public readonly selectedArtist = this.selectedArtistSignal.asReadonly();
  public readonly selectMode = this.selectModeSignal.asReadonly();
  public readonly submitting = this.submittingSignal.asReadonly();

  // Data from Query services
  public readonly tracks = this.trackQueryService.tracks;
  public readonly pagination = this.trackQueryService.pagination;
  public readonly loading = this.trackQueryService.isLoading;
  public readonly genres = this.genreQueryService.genreNames;
  public readonly selectedTracks = this.trackQueryService.selectedTracks;
  public readonly hasSelectedTracks = this.trackQueryService.hasSelectedTracks;

  // Computed values
  public readonly artists = computed(() => {
    const uniqueArtists = new Set(
      this.tracks()
        .map(track => track.artist)
        .filter(artist => isDefined(artist) && artist.trim().length > 0)
    );
    return Array.from(uniqueArtists).sort();
  });

  public readonly currentPlayingTrack = computed(() => {
    // If we have Signal-based AudioService, use it
    // For now using existing service
    return null; // TODO: Update when we create AudioPlaybackSignalService
  });

  // Subject for search with debounce
  private searchSubject = new Subject<string>();

  public ngOnInit(): void {
    this.setupSearchDebounce();
    this.setupEffects();
  }

  private setupSearchDebounce(): void {
    this.searchSubject
      .pipe(
        debounceTime(UI_TIMING.SEARCH_DEBOUNCE_MS),
        distinctUntilChanged(),
        takeUntilDestroyed(this.destroyRef)
      )
      .subscribe(searchText => {
        this.updateFilters({ search: searchText, page: 0 });
      });
  }

  private setupEffects(): void {
    // Effect for automatically updating filters when local state changes
    effect(() => {
      const genre = this.selectedGenre();
      const artist = this.selectedArtist();

      if (genre.length > 0 || artist.length > 0) {
        const filters: Partial<TrackFilters> = { page: 0 };
        if (genre.length > 0) filters.genre = genre;
        if (artist.length > 0) filters.artist = artist;
        this.updateFilters(filters);
      }
    });
  }

  // === FILTER METHODS ===
  public onSearchChange(searchText: string): void {
    this.searchTextSignal.set(searchText);
    this.searchSubject.next(searchText);
  }

  public onGenreChange(event: MatSelectChange): void {
    const value = event.value as string | undefined;
    this.selectedGenreSignal.set(value ?? '');
  }

  public onArtistChange(event: MatSelectChange): void {
    const value = event.value as string | undefined;
    this.selectedArtistSignal.set(value ?? '');
  }

  public onSortChange(event: MatSelectChange): void {
    const value = event.value as string;
    const [field, order] = value.split(':');
    const filters: Partial<TrackFilters> = { page: 0 };
    if (field != null) filters.sort = field;
    if (order != null) filters.order = order as 'asc' | 'desc';
    this.updateFilters(filters);
  }

  public onPageChange(event: PageEvent): void {
    this.updateFilters({
      page: event.pageIndex,
      limit: event.pageSize
    });
  }

  public clearFilters(): void {
    this.searchTextSignal.set('');
    this.selectedGenreSignal.set('');
    this.selectedArtistSignal.set('');
    this.trackQueryService.resetFilters();
  }

  private updateFilters(newFilters: Partial<TrackFilters>): void {
    this.trackQueryService.updateFilters(newFilters);
  }

  // === TRACK OPERATIONS ===
  public onTrackPlay(track: Track): void {
    this.audioService.playTrack(track);
    // Handle result if needed
  }

  public async onTrackEdit(track: Track): Promise<void> {
    const dialogRef = await this.lazyModalService.openTrackEditModal({
      width: MODAL_DIMENSIONS.TRACK_EDIT_WIDTH,
      data: { track }
    });

    dialogRef.afterClosed().subscribe(result => {
      if (result != null) {
        this.trackQueryService.refreshTracks();
      }
    });
  }

  public async onTrackDelete(track: Track): Promise<void> {
    const dialogRef = await this.lazyModalService.openTrackDeleteModal({
      width: MODAL_DIMENSIONS.TRACK_DELETE_WIDTH,
      data: { track }
    });

    dialogRef.afterClosed().subscribe(result => {
      if (result != null) {
        this.trackQueryService.refreshTracks();
      }
    });
  }

  public async onTrackUpload(track: Track): Promise<void> {
    const dialogRef = await this.lazyModalService.openTrackUploadModal({
      width: MODAL_DIMENSIONS.TRACK_UPLOAD_WIDTH,
      data: { track }
    });

    dialogRef.afterClosed().subscribe(result => {
      if (result != null) {
        this.trackQueryService.refreshTracks();
      }
    });
  }

  public onTrackSelect(event: { track: Track; selected: boolean }): void {
    this.trackQueryService.toggleTrackSelection(event.track.id);
  }

  // === BULK OPERATIONS ===
  public toggleSelectMode(): void {
    this.selectModeSignal.update(current => !current);
    if (!this.selectMode()) {
      this.trackQueryService.clearSelection();
    }
  }

  public selectAllTracks(): void {
    this.trackQueryService.selectAllTracks();
  }

  public clearSelection(): void {
    this.trackQueryService.clearSelection();
  }

  public async bulkDeleteSelected(): Promise<void> {
    const selectedIds = this.trackQueryService.selectedTrackIds();

    if (selectedIds.length === 0) return;

    const dialogRef = await this.lazyModalService.openTrackDeleteModal({
      width: MODAL_DIMENSIONS.TRACK_DELETE_WIDTH,
      data: {
        bulk: true,
        trackIds: selectedIds,
        count: selectedIds.length
      }
    });

    dialogRef.afterClosed().subscribe(result => {
      if (result != null) {
        this.trackQueryService.refreshTracks();
        this.selectModeSignal.set(false);
      }
    });
  }

  // === CRUD OPERATIONS ===
  public async createTrack(): Promise<void> {
    const dialogRef = await this.lazyModalService.openTrackCreateModal({
      width: MODAL_DIMENSIONS.TRACK_CREATE_WIDTH
    });

    dialogRef.afterClosed().subscribe(result => {
      if (result != null) {
        this.trackQueryService.refreshTracks();
        this.snackBar.open('Track created successfully', 'Close', {
          duration: UI_TIMING.SNACKBAR_DURATION_MS
        });
      }
    });
  }

  public refreshTracks(): void {
    this.trackQueryService.refreshTracks();
  }

  // === UTILITY METHODS ===
  public isTrackSelected(trackId: string): boolean {
    return this.trackQueryService.isTrackSelected(trackId);
  }

  public getTrackById(id: string): Track | undefined {
    return this.tracks().find(track => track.id === id);
  }

  // === TEMPLATE HELPERS ===
  public get sortOptions(): { value: string; label: string }[] {
    return [
      { value: 'createdAt:desc', label: 'Newest First' },
      { value: 'createdAt:asc', label: 'Oldest First' },
      { value: 'title:asc', label: 'Title A-Z' },
      { value: 'title:desc', label: 'Title Z-A' },
      { value: 'artist:asc', label: 'Artist A-Z' },
      { value: 'artist:desc', label: 'Artist Z-A' }
    ];
  }
}

import {
  AfterViewInit,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  DestroyRef,
  ElementRef,
  EventEmitter,
  HostListener,
  inject,
  Input,
  OnDestroy,
  OnInit,
  Output,
  ViewChild
} from '@angular/core';
import {NgIf} from '@angular/common';
import WaveSurfer from 'wavesurfer.js';
import {takeUntilDestroyed} from '@angular/core/rxjs-interop';
import {MatIconButton} from '@angular/material/button';
import {MatIcon} from '@angular/material/icon';
import {MatProgressSpinner} from '@angular/material/progress-spinner';
import {AudioPlaybackService, AudioState, AudioPriorityService} from '@app/processes';
import {
  ApiConfigService,
  assertDefined,
  createUnknownError,
  DomainError,
  isDefined,
  Result,
  TestIdDirective,
  OptimizedImageComponent
} from '@app/shared';
import {Track} from '@app/entities';

@Component({
  selector: 'app-track-player',
  standalone: true,
  imports: [
    TestIdDirective,
    NgIf,
    MatIconButton,
    MatIcon,
    MatProgressSpinner,
    OptimizedImageComponent
  ],
  templateUrl: './track-player.component.html',
  styleUrl: './track-player.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class TrackPlayerComponent implements OnInit, AfterViewInit, OnDestroy {
  @Input() public track: Track | null = null;
  @Output() public playerClose = new EventEmitter<void>();

  @ViewChild('waveformRef') waveformRef!: ElementRef;

  public audioState!: AudioState;
  public wavesurfer: WaveSurfer | null = null;
  public waveformReady = false;
  public dragging = false;
  private lastVolume = 0;
  private initializationInProgress = false;
  private componentDestroyed = false;
  private pendingPlayback = false;

  private destroyRef = inject(DestroyRef);
  private apiConfig = inject(ApiConfigService);
  private audioService = inject(AudioPlaybackService);
  private audioPriorityService = inject(AudioPriorityService);
  private cdr = inject(ChangeDetectorRef);

  @HostListener('window:beforeunload')
  public beforeUnload(): void {
    if (this.audioState.isPlaying) {
      const stopResult = this.audioService.stop();
      Result.match(
        stopResult,
        () => { /* no-op */ },
        (error: unknown) => {
          console.warn('Failed to stop audio on page unload:', error);
        }
      );
    }
  }

  public ngOnInit(): void {
    this.audioState = {
      track: null,
      isPlaying: false,
      currentTime: 0,
      duration: 0,
      volume: 1,
      error: null
    };

    this.audioPriorityService.setManualTrack(this.track);

    this.audioService.audioState$
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe(state => {
        if (this.track === null || this.audioState.track === null || state.track?.id === this.track.id) {
          this.audioState = state;

          if (this.track !== null && state.isPlaying && !this.waveformReady && state.track?.id === this.track.id) {
            console.log('Audio started playing but waveform is not ready yet, pausing temporarily');
            this.audioService.pause();
            this.pendingPlayback = true;
          }

          if (this.track !== null && isDefined(this.wavesurfer) && this.waveformReady && !this.dragging) {
            if (state.track?.id === this.track.id && state.duration > 0) {
              const position = state.currentTime / Math.max(state.duration, 0.1);
              if (position >= 0 && position <= 1 && isDefined(this.wavesurfer)) {
                this.wavesurfer.seekTo(position);
              }
            }
          }

          this.cdr.markForCheck();
        }
      });
  }

  public ngAfterViewInit(): void {
    if (this.track === null) {
      console.warn('TrackPlayerComponent: track is null in ngAfterViewInit');
      return;
    }
    setTimeout(() => {
      void this.initWaveSurfer();
    });
  }

  public ngOnDestroy(): void {
    this.componentDestroyed = true;
    this.destroyWaveSurfer();

    if (this.track !== null && this.audioState.isPlaying && this.audioState.track?.id === this.track.id) {
      const stopResult = this.audioService.stop();
      Result.match(
        stopResult,
        () => { /* no-op */ },
        (error: unknown) => {
          console.warn('Failed to stop audio on component destroy:', error);
        }
      );
    }

    this.audioPriorityService.closeManualPlayer();
  }

  private destroyWaveSurfer(): void {
    if (isDefined(this.wavesurfer)) {
      // Direct execution instead of safeExecute
      this.wavesurfer.pause();
      this.wavesurfer.destroy();
      this.wavesurfer = null;
      this.waveformReady = false;
    }

    if (isDefined(this.waveformRef.nativeElement)) {
      // Direct DOM manipulation
      const container = this.waveformRef.nativeElement as HTMLElement;
      while (isDefined(container.firstChild)) {
        container.removeChild(container.firstChild);
      }
    }
  }

  private async initWaveSurfer(): Promise<void> {
    if (this.track === null) {
      console.warn('TrackPlayerComponent: track is null, cannot initialize WaveSurfer');
      return;
    }

    if (this.componentDestroyed) {
      console.log('Component destroyed, skipping WaveSurfer initialization');
      return;
    }

    if (this.initializationInProgress) {
      console.log('Initialization of WaveSurfer is already in progress, skipping');
      return;
    }

    this.initializationInProgress = true;

    if (!isDefined(this.track.audioFile) || this.track.audioFile === '') {
      console.error('Track has no audio file, cannot initialize wavesurfer');
      this.initializationInProgress = false;
      return;
    }

    if (this.waveformRef.nativeElement === null || this.waveformRef.nativeElement === undefined) {
      this.initializationInProgress = false;
      console.error('Waveform element reference is not available');
      return;
    }

    const waveformElement = this.waveformRef.nativeElement as HTMLElement;
    this.destroyWaveSurfer();

    const audioFileUrl = this.getFullAudioUrl(this.track.audioFile);
    console.log('WaveSurfer loading from URL:', audioFileUrl);

        // Create WaveSurfer using Result monads
    const setupResult = this.createWaveSurfer(waveformElement);

    Result.match(
      setupResult,
      (ws: WaveSurfer) => {
        this.wavesurfer = ws;
      },
      (error) => {
        console.error('Error creating WaveSurfer:', error);
        this.waveformReady = false;
        this.initializationInProgress = false;
        this.pendingPlayback = false;
        this.cdr.markForCheck();
        return;
      }
    );

    if (!isDefined(this.wavesurfer)) {
      return;
    }

    const wavesurferInstance = this.wavesurfer;

    wavesurferInstance.on('ready', () => {
      console.log('WaveSurfer is ready');
      this.waveformReady = true;

      if (this.audioState.currentTime > 0 && this.audioState.duration > 0) {
        const position = this.audioState.currentTime / this.audioState.duration;
        wavesurferInstance.seekTo(position);
      }

      this.initializationInProgress = false;
      if (this.pendingPlayback) {
        console.log('Waveform is ready, resuming pending playback');
        this.pendingPlayback = false;
        setTimeout(() => {
          void this.audioService.play();
        }, 100);
      }

      this.cdr.markForCheck();
    });

    wavesurferInstance.on('error', (error: unknown) => {
      console.error('WaveSurfer error:', error);
      this.waveformReady = false;
      this.initializationInProgress = false;
      this.cdr.markForCheck();
    });

    wavesurferInstance.on('interaction', () => {
      this.dragging = true;
    });

    (wavesurferInstance as WaveSurfer & { on(event: 'seek', callback: (position: number) => void): void }).on('seek', (position: number) => {
      console.log('WaveSurfer seek event:', position);
      if (this.track !== null && this.audioState.track?.id === this.track.id) {
        const seekTime = position * this.audioState.duration;
        const seekResult = this.audioService.seek(seekTime);
        Result.match(
          seekResult,
          () => { /* no-op */ },
          (error: unknown) => {
            console.error('Failed to seek audio:', error);
          }
        );
      }

      setTimeout(() => {
        this.dragging = false;
      }, 100);
    });

    // Load audio file using Result monads
    const loadResult = await this.loadAudioFile(wavesurferInstance, audioFileUrl);
    Result.match(
      loadResult,
      () => { /* no-op */ },
      (error) => {
        console.error('Error loading audio file:', error);
        this.waveformReady = false;
        this.initializationInProgress = false;
        this.pendingPlayback = false;
        this.cdr.markForCheck();
        return;
      }
    );

    setTimeout(() => {
      if (!this.waveformReady && !this.componentDestroyed) {
        console.warn('WaveSurfer download timeout - possibly problems with downloading the audio file');
        this.initializationInProgress = false;
      }
    }, 10000);
  }

  public togglePlayPause(): void {
    if (this.track === null) {
      console.warn('TrackPlayerComponent: track is null in togglePlayPause');
      return;
    }

    if (!this.waveformReady) {
      console.log('Waveform not ready yet, setting pending playback');
      this.pendingPlayback = true;
      this.cdr.markForCheck();
      return;
    }

    if (this.audioState.track?.id !== this.track.id) {
      this.audioService.playTrack(this.track);
    } else {
      this.audioService.togglePlayPause();
    }
  }

  public onClosePlayer(): void {
    const stopResult = this.audioService.stop();
    Result.match(
      stopResult,
      () => { /* no-op */ },
      (error: unknown) => {
        console.warn('Failed to stop audio when closing player:', error);
      }
    );

    this.destroyWaveSurfer();

    this.audioPriorityService.closeManualPlayer();

    this.playerClose.emit();
  }

  public formatTime(seconds: number): string {
    if (seconds === 0 || isNaN(seconds)) return '0:00';

    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${String(mins)}:${secs < 10 ? '0' : ''}${String(secs)}`;
  }

  public toggleMute(): void {
    if (this.audioState.volume > 0) {
      this.lastVolume = this.audioState.volume;
      const muteResult = this.audioService.setVolume(0);
      Result.match(
        muteResult,
        () => { /* no-op */ },
        (error: unknown) => {
          console.error('Failed to mute audio:', error);
        }
      );
    } else {
      const volumeToRestore = this.lastVolume === 0 ? 0.7 : this.lastVolume;
      const unmuteResult = this.audioService.setVolume(volumeToRestore);
      Result.match(
        unmuteResult,
        () => { /* no-op */ },
        (error: unknown) => {
          console.error('Failed to unmute audio:', error);
        }
      );
    }
  }

  public onVolumeChange(event: Event): void {
    assertDefined(event.target, 'Event target must be defined');
    const input = event.target as HTMLInputElement;
    const volume = parseFloat(input.value);
    const volumeResult = this.audioService.setVolume(volume);

    Result.match(
      volumeResult,
      () => {
        if (volume > 0) {
          this.lastVolume = volume;
        }
      },
      (error: unknown) => {
        console.error('Failed to change volume:', error);
      }
    );
  }

  public onTimelineClick(event: MouseEvent): void {
    if (this.audioState.duration === 0) return;

    assertDefined(event.currentTarget, 'Event currentTarget must be defined');
    const timeline = event.currentTarget as HTMLElement;
    const rect = timeline.getBoundingClientRect();
    const ratio = (event.clientX - rect.left) / rect.width;
    const seekTime = ratio * this.audioState.duration;

    const seekResult = this.audioService.seek(seekTime);
    Result.match(
      seekResult,
      () => { /* no-op */ },
      (error: unknown) => {
        console.error('Failed to seek via timeline:', error);
      }
    );
  }

  public get isPlaying(): boolean {
    return this.track !== null && this.audioState.isPlaying && this.audioState.track?.id === this.track.id;
  }

  public get progressPercent(): number {
    if (this.audioState.duration === 0) return 0;
    return (this.audioState.currentTime / this.audioState.duration) * 100;
  }

  private getFullAudioUrl(audioFilePath: string): string {
    if (audioFilePath.startsWith('http://') || audioFilePath.startsWith('https://')) {
      return audioFilePath;
    }
    return this.apiConfig.getUrl(`files/${audioFilePath}`);
  }

    private createWaveSurfer(waveformElement: HTMLElement): Result<WaveSurfer, DomainError> {
    // Clear container
    const container = this.waveformRef.nativeElement as HTMLElement;
    while (isDefined(container.firstChild)) {
      container.removeChild(container.firstChild);
    }

    // Create WaveSurfer instance with Result monads
    const waveSurfer = WaveSurfer.create({
      container: waveformElement,
      height: 80,
      waveColor: '#9e9e9e',
      progressColor: '#1976d2',
      cursorColor: '#f44336',
      cursorWidth: 2,
      barWidth: 2,
      barGap: 1,
      barRadius: 2,
      normalize: true,
      fillParent: true,
      backend: 'WebAudio',
      hideScrollbar: true,
      interact: false,
    });

    return Result.Ok(waveSurfer);
  }

  private async loadAudioFile(wavesurfer: WaveSurfer, audioFileUrl: string): Promise<Result<void, DomainError>> {
    return await wavesurfer.load(audioFileUrl).then(
      () => Result.Ok(undefined),
      (error: unknown) => Result.Error(createUnknownError(
        error instanceof Error ? error.message : 'Failed to load audio file',
        {originalError: error}
      ))
    );
  }
}

import { Component, EventEmitter, Input, Output } from '@angular/core';
import { Subject } from 'rxjs';
import { debounceTime, distinctUntilChanged } from 'rxjs/operators';
import { assertDefined } from '@app/shared';

@Component({
  selector: 'app-track-search',
  standalone: true,
  imports: [],
  templateUrl: './track-search.component.html',
  styleUrl: './track-search.component.scss'
})
export class TrackSearchComponent {
  @Input() placeholder = 'Search tracks...';
  @Input() debounceTime = 300;
  @Input() value = '';

  @Output() searchChange = new EventEmitter<string>();

  private searchSubject = new Subject<string>();

  constructor() {
    this.searchSubject.pipe(
      debounceTime(this.debounceTime),
      distinctUntilChanged()
    ).subscribe(searchTerm => {
      this.searchChange.emit(searchTerm);
    });
  }

  onInput(event: Event): void {
    assertDefined(event.target, 'Event target must be defined');
    const input = event.target as HTMLInputElement;
    this.value = input.value;
    this.searchSubject.next(input.value);
  }

  clearSearch(): void {
    this.value = '';
    this.searchChange.emit('');
  }
}

