import { Component, EventEmitter, Input, Output } from '@angular/core';

export interface SortOption {
  value: string;
  label: string;
}

export interface SortConfig {
  field: string;
  order: 'asc' | 'desc';
}

@Component({
  selector: 'app-track-sort',
  standalone: true,
  imports: [],
  templateUrl: './track-sort.component.html',
  styleUrl: './track-sort.component.scss'
})
export class TrackSortComponent {
  @Input() currentSort: SortConfig = { field: 'createdAt', order: 'desc' };
  @Input() sortOptions: SortOption[] = [
    { value: 'title', label: 'Title' },
    { value: 'artist', label: 'Artist' },
    { value: 'album', label: 'Album' },
    { value: 'createdAt', label: 'Date Added' }
  ];

  @Output() sortChange = new EventEmitter<SortConfig>();

  onSortFieldChange(field: string): void {
    this.sortChange.emit({ ...this.currentSort, field });
  }

  onSortOrderChange(order: 'asc' | 'desc'): void {
    this.sortChange.emit({ ...this.currentSort, order });
  }

  toggleSortOrder(): void {
    const newOrder = this.currentSort.order === 'asc' ? 'desc' : 'asc';
    this.sortChange.emit({ ...this.currentSort, order: newOrder });
  }
}

import { ChangeDetectionStrategy, Component } from '@angular/core';
import { RouterModule } from '@angular/router';
import { CommonModule } from '@angular/common';
import { MatProgressSpinner } from '@angular/material/progress-spinner';
import { TestIdDirective } from '@app/shared';
import { TrackListWidgetComponent } from '@app/widgets';
import { ActiveTrackWidgetComponent } from '@app/widgets/active-track-widget/active-track-widget.component';

@Component({
  selector: 'app-tracks-page',
  standalone: true,
  imports: [
    CommonModule,
    RouterModule,
    TrackListWidgetComponent,
    ActiveTrackWidgetComponent,
    TestIdDirective,
    MatProgressSpinner,
  ],
  templateUrl: './tracks-page.component.html',
  styleUrl: './tracks-page.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class TracksPageComponent {
  public pageTitle = 'Music Tracks';
}

import { ChangeDetectionStrategy, ChangeDetectorRef, Component, DestroyRef, Inject, inject } from '@angular/core';
import {
  MAT_DIALOG_DATA,
  MatDialogActions,
  MatDialogContent,
  MatDialogRef,
  MatDialogTitle
} from '@angular/material/dialog';
import { NgIf } from '@angular/common';
import { MatIcon } from '@angular/material/icon';
import { MatProgressSpinner } from '@angular/material/progress-spinner';
import { MatButton } from '@angular/material/button';
import { TestIdDirective, ToastService, isDefined, assertDefined } from '@app/shared';
import { Track, TrackQueryService } from '@app/entities';

interface DialogData {
  track: Track;
}

@Component({
  selector: 'app-track-upload-modal',
  standalone: true,
  imports: [
    MatDialogTitle,
    MatDialogContent,
    NgIf,
    MatIcon,
    MatButton,
    TestIdDirective,
    MatDialogActions,
    MatProgressSpinner
  ],
  templateUrl: './track-upload-modal.component.html',
  styleUrl: './track-upload-modal.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class TrackUploadModalComponent {
  public uploading = false;
  public file: File | null = null;
  public error: string | null = null;
  public hasExistingFile = false;
  public uploadProgress = 0;

  constructor(
    private trackQueryService: TrackQueryService,
    private dialogRef: MatDialogRef<TrackUploadModalComponent>,
    private toast: ToastService,
    private cdr: ChangeDetectorRef,
    @Inject(MAT_DIALOG_DATA) public data: DialogData
  ) {
    this.hasExistingFile = isDefined(this.data.track.audioFile);
  }
  private destroyRef = inject(DestroyRef);

  public onFileSelected(event: Event): void {
    assertDefined(event.target, 'Event target must be defined');
    const input = event.target as HTMLInputElement;

    if (input.files === null || input.files.length === 0) {
      this.file = null;
      return;
    }

    const file = input.files[0];
    if (file === undefined) {
      this.file = null;
      return;
    }

    if (!this.isAudioFile(file)) {
      this.error = 'Invalid file type. Please upload an audio file (MP3, WAV, OGG).';
      this.file = null;
      this.cdr.markForCheck();
      return;
    }

    if (file.size > 20 * 1024 * 1024) {
      this.error = 'File size exceeds 20MB. Please upload a smaller file.';
      this.file = null;
      this.cdr.markForCheck();
      return;
    }

    this.file = file;
    this.error = null;
    this.cdr.markForCheck();
  }

  public uploadFile(): void {
    if (!isDefined(this.file)) {
      this.error = 'Please select a file to upload.';
      return;
    }

    const fileToUpload = this.file;

    this.uploading = true;
    this.error = null;

    this.trackQueryService.uploadFile(this.data.track.id, fileToUpload)
      .then((track: Track) => {
        this.uploading = false;
        this.uploadProgress = 100;
        this.toast.success('File uploaded successfully');
        this.dialogRef.close(track);
        this.cdr.markForCheck();

        setTimeout(() => {
          this.uploadProgress = 0;
          this.cdr.markForCheck();
        }, 1000);
      })
      .catch((error: unknown) => {
        this.uploading = false;
        console.error('Failed to upload file', error);
        this.error = 'Failed to upload file. Please try again.';
        this.toast.error('Failed to upload file');
        this.cdr.markForCheck();
      });
  }

  public deleteFile(): void {
    this.uploading = true;

    this.trackQueryService.deleteFile(this.data.track.id)
      .then((track: Track) => {
        this.uploading = false;
        this.toast.success('File deleted successfully');
        this.dialogRef.close(track);
        this.cdr.markForCheck();
      })
      .catch((error: unknown) => {
        this.uploading = false;
        console.error('Failed to delete file', error);
        this.error = 'Failed to delete file. Please try again.';
        this.toast.error('Failed to delete file');
        this.cdr.markForCheck();
      });
  }

  public onCancel(): void {
    this.dialogRef.close();
  }

  public getFilename(): string {
    if (isDefined(this.file)) {
      return this.file.name;
    }

    if (isDefined(this.data.track.audioFile)) {
      const parts = this.data.track.audioFile.split('/');
      return parts[parts.length - 1] ?? '';
    }

    return '';
  }

  private isAudioFile(file: File): boolean {
    const validTypes = ['audio/mpeg', 'audio/wav', 'audio/ogg', 'audio/mp3', 'audio/x-wav'];
    return validTypes.includes(file.type);
  }

  private simulateProgress(): void {
    this.uploadProgress = 0;
    const interval = setInterval(() => {
      if (this.uploadProgress >= 90) {
        clearInterval(interval);
      } else {
        const increment = this.uploadProgress < 30 ? 10 :
          this.uploadProgress < 60 ? 5 : 2;
        this.uploadProgress += increment;
        this.cdr.markForCheck();
      }
    }, 300);
  }
}

